content.query:
OktaSSO
| where domain_s in ({Domain}) or '*' in ({Domain})
//| where authenticationContext_externalSessionId_s in ({SessionID})
//| extend actor_alternateId_s=replace_string(actor_alternateId_s,@'\','')
| where actor_alternateId_s in ({User}) or '*' in ({User})
//| where eventType_s in ({EventTypes}) or '*' in ({EventTypes})
| summarize count(eventType_s) by 	City = client_geographicalContext_city_s, actor_alternateId_s, Country = client_geographicalContext_country_s, latitude = client_geographicalContext_geolocation_lat_d, longitude = client_geographicalContext_geolocation_lon_d,  Results = outcome_result_s

